import math


def _num(d, key, default=0.0):
    if not isinstance(d, dict):
        return float(default)
    v = d.get(key, default)
    if v is None:
        return float(default)
    try:
        f = float(v)
    except (TypeError, ValueError):
        return float(default)
    if math.isnan(f) or math.isinf(f):
        return float(default)
    return f


def _mag(v):
    if v is None:
        return 0.0
    if isinstance(v, (int, float)):
        f = float(v)
        return 0.0 if (math.isnan(f) or math.isinf(f)) else abs(f)
    if isinstance(v, (list, tuple)):
        vals = [_mag(c) for c in v]
        return math.sqrt(sum(c * c for c in vals))
    if isinstance(v, dict):
        vals = [_mag(c) for c in v.values()]
        return math.sqrt(sum(c * c for c in vals))
    return 0.0


def _clamp(x, lo, hi):
    return max(lo, min(hi, x))


def score(ep: dict) -> float:
    outcome = ep.get("outcome", "")
    success = bool(ep.get("success", False) or outcome == "success")
    fell = bool(ep.get("fell", False) or outcome == "fell")
    collided = bool(ep.get("collided", False) or outcome == "collided")
    near_miss = bool(ep.get("near_miss", False) or outcome == "near_miss")
    stalled = bool(ep.get("stalled", False) or outcome == "stalled")
    timeout = bool(outcome == "timeout")

    duration = max(0.0, _num(ep, "duration", 0.0))
    peak_impact = max(0.0, _num(ep, "peak_impact", 0.0))
    max_tilt_deg = max(0.0, _num(ep, "max_tilt_deg", 0.0))
    jerk = max(0.0, _num(ep, "jerk", 0.0))

    edge_speed_raw = ep.get("edge_speed", None)
    edge_heading_raw = ep.get("edge_heading_deg", None)
    min_clearance_raw = ep.get("min_clearance", None)

    states = ep.get("states") or []
    n = len(states)

    # 1. Forward progress & post-curb progression (curb is near x = 0.0)
    start_x = -1.0
    final_x = start_x
    max_x = start_x
    backtrack_m = 0.0
    pre_curb_frac = 0.0
    post_curb_frac = 0.0

    if n > 0:
        start_x = _num(states[0], "x", -1.0)
        final_x = _num(states[-1], "x", start_x)
        max_x = max(_num(s, "x", start_x) for s in states)
        backtrack_m = max(0.0, max_x - final_x)

        pre_span = max(0.25, 0.0 - start_x)
        pre_curb_frac = _clamp((min(final_x, 0.0) - start_x) / pre_span, -0.5, 1.0)
        post_curb_frac = _clamp(final_x / 1.1, 0.0, 1.0)
    else:
        pre_curb_frac = 1.0 if success else 0.0
        post_curb_frac = 1.0 if success else 0.0

    bonus_gate = 1.0 if (success and not fell and not collided) else 0.0

    total = 0.0
    # Keep pre-curb progress modest so stopping at the curb never outweighs stall penalty;
    # heavily reward actually getting across the curb (x > 0) and stabilizing on the upper surface.
    total += 12.0 * pre_curb_frac
    total += 55.0 * post_curb_frac
    if max_x > 0.02:
        total += 20.0 * _clamp((max_x - 0.02) / 0.8, 0.0, 1.0)
    total -= 18.0 * _clamp(backtrack_m, 0.0, 1.5)

    # 2. Strict terminal outcome hierarchy (failures must always score well below 0)
    if success and not fell and not collided:
        total += 140.0
        if duration > 0.0:
            total += _clamp(15.0 - 1.5 * max(0.0, duration - 2.5), 0.0, 15.0)

    if fell:
        total -= 150.0
    if collided:
        total -= 140.0
    if near_miss:
        total -= 60.0
    if stalled:
        total -= 90.0
    if timeout and not success:
        total -= 60.0

    # 3. Curb edge alignment & controlled climb speed (prevent both stalling and high-speed ramming)
    if edge_heading_raw is not None:
        edge_heading = abs(_num(ep, "edge_heading_deg", 0.0))
        total -= 0.6 * edge_heading + 0.04 * (edge_heading ** 2)
        if edge_heading < 8.0:
            total += bonus_gate * 10.0 * ((8.0 - edge_heading) / 8.0) ** 2

    if edge_speed_raw is not None:
        edge_speed = max(0.0, _num(ep, "edge_speed", 0.0))
        # Ideal curb climb speed is 0.45 - 0.80 m/s: enough momentum to climb without slamming or flipping
        if edge_speed > 0.85:
            excess_v = edge_speed - 0.85
            total -= 25.0 * excess_v + 30.0 * (excess_v ** 2)
        elif edge_speed < 0.40 and not success:
            total -= 12.0 * ((0.40 - edge_speed) / 0.40)
        if 0.45 <= edge_speed <= 0.80:
            center_err = abs(edge_speed - 0.625) / 0.175
            total += bonus_gate * 12.0 * max(0.0, 1.0 - center_err ** 2)

    # 4. Unconditional impact & tilt stability penalties (never exempt stalled episodes)
    if peak_impact > 50.0:
        imp_excess = peak_impact - 50.0
        total -= _clamp(0.75 * imp_excess + 0.02 * (imp_excess ** 2), 0.0, 60.0)
    elif peak_impact < 50.0:
        total += bonus_gate * 10.0 * ((50.0 - peak_impact) / 50.0)

    if max_tilt_deg > 24.0:
        tilt_excess = max_tilt_deg - 24.0
        total -= _clamp(1.8 * tilt_excess + 0.12 * (tilt_excess ** 2), 0.0, 60.0)
    elif max_tilt_deg < 22.0:
        total += bonus_gate * 8.0 * ((22.0 - max_tilt_deg) / 22.0)

    # 5. Unconditional command smoothness
    if jerk > 2.0:
        jerk_excess = jerk - 2.0
        total -= _clamp(5.0 * jerk_excess + 1.2 * (jerk_excess ** 2), 0.0, 40.0)
    else:
        total += bonus_gate * 8.0 * ((2.0 - jerk) / 2.0) ** 2

    # 6. Obstacle & pedestrian clearance
    if min_clearance_raw is not None:
        clearance = max(0.0, _num(ep, "min_clearance", 0.0))
        safe_dist = 0.90
        if clearance < safe_dist:
            deficit = (safe_dist - clearance) / safe_dist
            total -= 35.0 * (deficit ** 2)
            if clearance < 0.40:
                total -= 35.0 * ((0.40 - clearance) / 0.40)
        else:
            total += bonus_gate * 8.0 * _clamp((clearance - safe_dist) / 0.6, 0.0, 1.0)

    # 7. Per-tick trajectory stability, steady curb approach, and anti-flip shaping
    if n > 0:
        roll_pen_sum = 0.0
        pitch_pen_sum = 0.0
        heading_pen_sum = 0.0
        edge_zone_pen_sum = 0.0
        edge_zone_count = 0
        gyro_pen_sum = 0.0
        reverse_pen_sum = 0.0
        cmd_osc_sum = 0.0
        surging_pen_sum = 0.0
        lat_drift_sum = 0.0
        steady_approach_sum = 0.0
        approach_count = 0

        for i, s in enumerate(states):
            roll = abs(_num(s, "roll_deg", 0.0))
            pitch = abs(_num(s, "pitch_deg", 0.0))
            hdg_err = abs(_num(s, "heading_err_deg", 0.0))
            dist_edge = abs(_num(s, "dist_to_edge", 99.0))
            x_pos = _num(s, "x", 0.0)
            spd = _num(s, "speed", 0.0)
            cmd_v = _num(s, "cmd_v", spd)
            cmd_w = _num(s, "cmd_w", 0.0)
            y_pos = abs(_num(s, "y", 0.0))
            gyro_m = _mag(s.get("gyro", 0.0))

            if roll > 4.0:
                roll_pen_sum += 0.6 * (roll - 4.0) + 0.08 * ((roll - 4.0) ** 2)

            pitch_limit = 22.0 if dist_edge < 0.35 else 14.0
            if pitch > pitch_limit:
                pitch_pen_sum += 0.4 * (pitch - pitch_limit) + 0.05 * ((pitch - pitch_limit) ** 2)

            if hdg_err > 5.0:
                heading_pen_sum += 0.2 * (hdg_err - 5.0)
            if y_pos > 0.20:
                lat_drift_sum += 2.5 * (y_pos - 0.20)

            # Encourage controlled, aligned speed in the approach zone (-0.65 <= x <= 0.15)
            if -0.65 <= x_pos <= 0.15:
                approach_count += 1
                if 0.45 <= spd <= 0.80 and hdg_err < 6.0 and roll < 5.0:
                    steady_approach_sum += 1.0 - (abs(spd - 0.625) / 0.175) ** 2
                elif spd > 0.90:
                    edge_zone_pen_sum += 8.0 * (spd - 0.90)

            if dist_edge < 0.35:
                edge_zone_count += 1
                edge_zone_pen_sum += 0.35 * hdg_err + 0.6 * roll + 2.5 * abs(cmd_w)

            gyro_limit = 2.2 if dist_edge < 0.35 else 1.4
            if gyro_m > gyro_limit:
                gyro_pen_sum += 1.5 * (gyro_m - gyro_limit)

            if cmd_v < -0.03:
                reverse_pen_sum += 5.0 * abs(cmd_v)

            if i > 0:
                prev = states[i - 1]
                dt = max(1e-3, _num(s, "t", i * 0.05) - _num(prev, "t", (i - 1) * 0.05))
                prev_cv = _num(prev, "cmd_v", _num(prev, "speed", 0.0))
                prev_cw = _num(prev, "cmd_w", 0.0)
                prev_spd = _num(prev, "speed", 0.0)
                prev_x = _num(prev, "x", 0.0)

                d_cv = abs(cmd_v - prev_cv) / dt
                d_cw = abs(cmd_w - prev_cw) / dt
                d_spd = abs(spd - prev_spd) / dt

                if d_cv > 1.2:
                    cmd_osc_sum += 0.7 * (d_cv - 1.2)
                if d_cw > 1.5:
                    cmd_osc_sum += 0.5 * (d_cw - 1.5)
                if dist_edge >= 0.25 and d_spd > 2.2:
                    surging_pen_sum += 0.6 * (d_spd - 2.2)
                if (x_pos - prev_x) < -0.004:
                    reverse_pen_sum += 15.0 * abs(x_pos - prev_x)

        inv_n = 1.0 / float(n)
        total -= _clamp(roll_pen_sum * inv_n * 6.0, 0.0, 30.0)
        total -= _clamp(pitch_pen_sum * inv_n * 5.0, 0.0, 25.0)
        total -= _clamp(heading_pen_sum * inv_n * 4.0, 0.0, 15.0)
        total -= _clamp(lat_drift_sum * inv_n * 4.0, 0.0, 15.0)
        total -= _clamp(gyro_pen_sum * inv_n * 4.5, 0.0, 20.0)
        total -= _clamp(reverse_pen_sum * inv_n * 6.0, 0.0, 25.0)
        total -= _clamp(cmd_osc_sum * inv_n * 4.0, 0.0, 25.0)
        total -= _clamp(surging_pen_sum * inv_n * 4.5, 0.0, 25.0)

        if edge_zone_count > 0:
            total -= _clamp((edge_zone_pen_sum / float(edge_zone_count)) * 3.0, 0.0, 25.0)

        if approach_count > 0 and not fell and not collided:
            # Small bounded shaping for controlled approach speed (max +6 pts, cannot offset stall)
            total += 6.0 * _clamp(steady_approach_sum / float(approach_count), 0.0, 1.0)

        mean_pen = (roll_pen_sum + pitch_pen_sum + cmd_osc_sum + surging_pen_sum + reverse_pen_sum) * inv_n
        if success and mean_pen < 0.6 and not fell and not collided:
            total += 10.0 * ((0.6 - mean_pen) / 0.6)

    return float(total)
